import numpy as np

input_grid = [
    [8, 8, 8, 6],
    [8, 8, 8, 6],
    [6, 8, 8, 8],
    [8, 8, 8, 8],
    [6, 8, 8, 6],
    [8, 8, 8, 6],
    [8, 6, 8, 8],
    [6, 8, 8, 8],
    [8, 6, 8, 8],
    [8, 6, 8, 8]
]

output_grid = [
    [8, 8, 8, 6],
    [8, 8, 8, 6],
    [6, 8, 8, 3],
    [3, 8, 8, 3],
    [3, 3, 3, 6],
    [8, 8, 8, 6],
    [8, 6, 8, 8],
    [6, 8, 8, 8],
    [8, 6, 8, 8],
    [8, 6, 8, 8]
]

inp = np.array(input_grid)
out = np.array(output_grid)

# Check each position: does it become 3?
print("Checking if each position becomes 3:")
for r in range(inp.shape[0]):
    for c in range(inp.shape[1]):
        if out[r, c] == 3 and inp[r, c] == 8:
            # Count nearby 6s (in adjacent rows and columns)
            count = 0
            for dr in range(0, 5):
                if dr == 0 and r == c:
                    continue  # Skip self
                for dc in range(min(3, inp.shape[1])):
                    nr, nc = r + dr, c + dc
                    if nr >= 0 and nr < inp.shape[0] and 0 <= nc < inp.shape[1]:
                        if inp[nr, nc] == 6:
                            count += 1

            # Also count vertically (same column, different rows)
            for dr in range(-5, 5):
                if dr == 0:
                    continue
                nr = r + dr
                if nr >= 0 and nr < inp.shape[0]:
                    if inp[nr, c] == 6:
                        count += 1

            # Check if other changed positions follow a pattern
            print(f"  ({r},{c}): nearby 6s={count}, block_above={sum(inp[r-dr-1:c-1] if c-1>0 else [])}")

            # Actually let me count more systematically
            nearby = []
            for dr in range(-5, 5):
                for dc in range(-3, 4):
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if nr >= 0 and nr < inp.shape[0] and 0 <= nc < inp.shape[1]:
                        if inp[nr, nc] == 6:
                            nearby.append((nr, nc, -dr * 3 + dc))

            print(f"    Nearby 6s: {nearby}")

